CREATE OR REPLACE PROCEDURE lab.raise_dept (p_dept numeric, p_pct numeric, OUT p_updated numeric)
LANGUAGE plpgsql
SET search_path = lab, public
AS $$
BEGIN
  UPDATE emp SET salary = round(salary * (1 + p_pct / 100), 2) WHERE dept_id = p_dept;
  GET DIAGNOSTICS p_updated = ROW_COUNT;
END;
$$;
